function getError() {
  return new Promise((resolve, reject) => {
    reject('Error handled');
  });
}

async function run() {
  try {
    const result = await getError();
    console.log(result);
  } catch (error) {
    console.log(error);
  }
}

run();

function task(message) {
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(message);
    }, 1000);
  });
}

async function runTasks() {
  try {
    const step1 = await task('Step 1');
    console.log(step1);

    const step2 = await task('Step 2');
    console.log(step2);

    const step3 = await task('Step 3');
    console.log(step3);
  } catch (error) {
    console.log(error);
  }
}

runTasks();

